head.script:
//
(function () {
  try {
    var v = localStorage.getItem('rv-theme');
    if (v === 'dark' || v === 'light') { document.documentElement.setAttribute('data-theme', v); }
  } catch (e) { }
})();
//

head.b:skin:
/* =====================================================================
   羅傑觀點評論 — 薄荷夜色風（淺色／深色雙主題，皆保持高對比）
   設計重點：
   1. 預設自動跟隨使用者裝置的「淺色／深色」設定；右上角按鈕可手動覆寫
   2. 暖黑底 + 深色卡片 + 薄荷綠強調；淺色模式為薄荷灰白底 + 深綠文字強調
   3. 粗黑體標題、圓角卡片、膠囊按鈕、細邊線（不靠重陰影）
   4. 手機版：底部浮動膠囊導覽；文章卡片出現「新」徽章（72 小時內）
   5. 深色模式下，圖片 LOGO 自動墊白色圓角底板，黑字 LOGO 也看得清楚
   ===================================================================== */

:root{
  color-scheme:light;
  /* 品牌色（僅用於 LOGO 與頁尾 R） */
  --brand:#FFC20E;

  --bg:#F3F6F4; --card:#FFFFFF; --card-2:#F6F9F7; --line:#DCE4DF;
  --strong:#0F1412; --ink:#232B27; --muted:#5C6963;

  --accent:#7EE2B8;            /* 薄荷綠：填色用 */
  --accent-ink:#0B6B4B;        /* 淺色底上的綠色文字／圖示 */
  --on-accent:#06261A;         /* 壓在薄荷綠填色上的文字 */
  --accent-soft:#E0F6EC; --accent-line:#BEE8D3;

  --chip:#EAEFEC; --chip-ink:#56635D;
  --pill-bg:#E5EBE7; --pill-active:#FFFFFF;
  --badge-bg:#1F7A58; --badge-ink:#FFFFFF;
  --btn-bg:#E0F6EC; --btn-ink:#0B6B4B; --btn-line:#BEE8D3;
  --ph-a:#D3F2E4; --ph-b:#9BE2C2; --ph-ink:#0B6B4B;
  --mark:rgba(126,226,184,.55);

  --up:#D9322B; --down:#0E8F5C;          /* 台股慣例：紅漲綠跌 */
  --logo-bg:transparent; --logo-pad:0;
  --footer:#101916;

  --r:20px; --r-s:14px;
  --sans:'Noto Sans TC','Microsoft JhengHei','PingFang TC',system-ui,sans-serif;
  --shadow-s:0 1px 2px rgba(15,30,25,.05),0 6px 20px rgba(15,30,25,.06);
  --shadow:0 14px 34px rgba(15,30,25,.13);
}
@media (prefers-color-scheme:dark){
  :root:not([data-theme='light']){
    color-scheme:dark;
    --bg:#0A0D0C; --card:#141817; --card-2:#1A1F1D; --line:#262D2A;
    --strong:#F4F7F5; --ink:#DCE3DF; --muted:#8F9A95;
    --accent:#7EE2B8; --accent-ink:#7EE2B8; --on-accent:#06261A;
    --accent-soft:#17302A; --accent-line:#2B5646;
    --chip:#1F2523; --chip-ink:#9AA6A1;
    --pill-bg:#1C2120; --pill-active:#3A4042;
    --badge-bg:#2B6B50; --badge-ink:#DDFBEC;
    --btn-bg:#1F4D3C; --btn-ink:#8FE9C4; --btn-line:#2F6A53;
    --ph-a:#1F4D3C; --ph-b:#12372A; --ph-ink:#7EE2B8;
    --mark:rgba(126,226,184,.28);
    --up:#FF6B63; --down:#34C78A;
    --logo-bg:#FFFFFF; --logo-pad:8px 16px;
    --footer:#070908;
    --shadow-s:none; --shadow:0 14px 34px rgba(0,0,0,.55);
  }
}
:root[data-theme='dark']{
    color-scheme:dark;
    --bg:#0A0D0C; --card:#141817; --card-2:#1A1F1D; --line:#262D2A;
    --strong:#F4F7F5; --ink:#DCE3DF; --muted:#8F9A95;
    --accent:#7EE2B8; --accent-ink:#7EE2B8; --on-accent:#06261A;
    --accent-soft:#17302A; --accent-line:#2B5646;
    --chip:#1F2523; --chip-ink:#9AA6A1;
    --pill-bg:#1C2120; --pill-active:#3A4042;
    --badge-bg:#2B6B50; --badge-ink:#DDFBEC;
    --btn-bg:#1F4D3C; --btn-ink:#8FE9C4; --btn-line:#2F6A53;
    --ph-a:#1F4D3C; --ph-b:#12372A; --ph-ink:#7EE2B8;
    --mark:rgba(126,226,184,.28);
    --up:#FF6B63; --down:#34C78A;
    --logo-bg:#FFFFFF; --logo-pad:8px 16px;
    --footer:#070908;
    --shadow-s:none; --shadow:0 14px 34px rgba(0,0,0,.55);
}

*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:16px;line-height:1.8;letter-spacing:.01em;-webkit-font-smoothing:antialiased;transition:background .35s,color .35s}
a{color:inherit;text-decoration:none;transition:color .2s,background .2s,border-color .2s}
img{max-width:100%;height:auto}
::selection{background:var(--accent);color:var(--on-accent)}
.wrap{max-width:1180px;margin:0 auto;padding:0 20px}

/* 隱藏 Blogger 預設導覽列 */
.navbar,#navbar-iframe{display:none!important;height:0!important}

/* ---------- 行情跑馬燈 ---------- */
.ticker-bar{background:var(--card);min-height:46px;border-bottom:1px solid var(--line);overflow:hidden;transition:background .35s}

/* ---------- 頁首 ---------- */
.masthead{background:var(--bg);transition:background .35s}
.masthead-inner{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;padding-top:22px;padding-bottom:12px}
.masthead .header{flex:1 1 320px;min-width:0}
.masthead .Header img,#Header1_headerimg{display:block;max-width:100%;max-height:104px;width:auto;height:auto;background:var(--logo-bg);padding:var(--logo-pad);border-radius:16px}
.masthead .Header .descriptionwrapper{margin:0}

/* 若 Header 未設定圖片 LOGO，使用 CSS 自繪的「R 潑墨 + 粗體標題」 */
.Header h1.title{margin:0;display:flex;align-items:center;gap:16px;font-weight:900;font-size:clamp(28px,5vw,44px);letter-spacing:.05em;line-height:1.25;color:var(--strong)}
.Header h1.title a{color:inherit}
.Header h1.title::before{content:'R';flex:0 0 auto;display:grid;place-items:center;width:56px;height:56px;background:var(--brand);border-radius:46% 54% 42% 58% / 55% 40% 60% 45%;font:italic 900 34px/1 var(--sans);color:#1A1405;transform:rotate(-8deg)}
.Header .description{margin:4px 0 0;font-size:12px;font-weight:500;letter-spacing:.36em;color:var(--muted);text-transform:none}

.mast-tools{display:flex;align-items:center;gap:10px;font-size:13px;color:var(--muted)}
.btn-sub{display:inline-block;background:var(--btn-bg);color:var(--btn-ink);border:1px solid var(--btn-line);font-weight:700;letter-spacing:.08em;padding:8px 20px;border-radius:999px;transition:background .2s,color .2s,transform .2s}
.btn-sub:hover{background:var(--accent);color:var(--on-accent);border-color:var(--accent);transform:translateY(-1px)}
.theme-btn{width:42px;height:42px;border-radius:50%;border:1px solid var(--btn-line);background:var(--btn-bg);color:var(--btn-ink);font-size:18px;cursor:pointer;line-height:1;transition:background .2s,color .2s}
.theme-btn:hover{background:var(--accent);color:var(--on-accent)}

/* ---------- 主導覽（桌面：分段膠囊） ---------- */
.mainnav{position:sticky;top:10px;z-index:60;padding:8px 0 0}
.mainnav .wrap{display:flex;gap:4px;overflow-x:auto;white-space:nowrap;scrollbar-width:none;width:min(1140px,calc(100% - 28px));padding:5px;background:var(--pill-bg);border:1px solid var(--line);border-radius:999px;transition:background .35s}
.mainnav .wrap::-webkit-scrollbar{display:none}
.mainnav a{flex:1 1 auto;text-align:center;color:var(--muted);font-weight:500;letter-spacing:.1em;padding:10px 24px;border-radius:999px}
.mainnav a:hover{color:var(--strong)}
.mainnav a.on{background:var(--pill-active);color:var(--accent-ink);font-weight:700;box-shadow:var(--shadow-s)}

/* ---------- 手機底部浮動導覽 ---------- */
.bottomnav{display:none}

/* ---------- 首頁分類大磚 ---------- */
.cat-tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:24px}
.cat-tile{display:block;position:relative;overflow:hidden;background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow-s);padding:18px 20px 20px;transition:transform .3s,border-color .3s,box-shadow .3s,background .35s}
.cat-tile::after{content:'';position:absolute;right:-26px;top:-26px;width:96px;height:96px;border-radius:50%;background:var(--accent-soft);transition:transform .45s}
.cat-tile b,.cat-tile strong,.cat-tile span{position:relative;z-index:1}
.cat-tile b{display:block;font-weight:900;font-size:26px;line-height:1;color:var(--accent-ink)}
.cat-tile strong{display:block;margin-top:8px;font-weight:700;font-size:19px;letter-spacing:.05em;color:var(--strong)}
.cat-tile span{display:block;margin-top:4px;font-size:13px;line-height:1.6;color:var(--muted)}
.cat-tile:hover{transform:translateY(-4px);border-color:var(--accent);box-shadow:var(--shadow)}
.cat-tile:hover::after{transform:scale(1.9)}

/* ---------- 版面 ---------- */
.layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:32px;padding:26px 0 64px}
.content{min-width:0}

.status-msg-wrap{margin:0 0 20px;font-size:14px}
.status-msg-body{background:var(--accent-soft);color:var(--accent-ink);font-weight:700;padding:11px 20px;border-radius:999px;text-align:left!important}
.status-msg-border{display:none}

/* ---------- 首頁/分類頁：卡片網格 ---------- */
.index-page .blog-posts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.blog-posts .date-outer,.blog-posts .date-posts{display:contents}
.blog-posts .clear{display:none}
.index-page .date-header{display:none}

.post-outer{background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow-s);position:relative;overflow:hidden;transition:background .35s,border-color .3s}
.index-page .post-outer{display:flex;flex-direction:column;transition:transform .3s,box-shadow .3s,border-color .3s}
.index-page .post-outer:hover{transform:translateY(-5px);box-shadow:var(--shadow);border-color:var(--accent-line)}
.index-page .post{padding:18px 24px 24px}
.index-page .post-header,.index-page .post-footer,.index-page .post-share-buttons{display:none}

.card-thumb{display:block;position:relative;aspect-ratio:16/9;overflow:hidden;background:var(--ph-a)}
.card-thumb img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .7s ease}
.post-outer:hover .card-thumb img{transform:scale(1.045)}
.card-thumb.noimg{display:grid;place-items:center;background:linear-gradient(135deg,var(--ph-a),var(--ph-b))}
.card-thumb.noimg span{font:italic 900 72px/1 var(--sans);color:var(--ph-ink);opacity:.9}
.card-tag{position:absolute;left:14px;top:14px;background:rgba(8,18,14,.74);color:#8FE9C4;font-weight:700;font-size:12px;letter-spacing:.1em;padding:3px 13px;border-radius:999px;-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}

.index-page h3.post-title{margin:0 0 6px;font-weight:700;font-size:20px;line-height:1.5;letter-spacing:.02em;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.index-page h3.post-title a{color:var(--strong)}
.index-page .post-outer:hover h3.post-title a{color:var(--accent-ink)}
.card-meta{display:flex;flex-wrap:wrap;align-items:center;gap:4px 12px;margin:0 0 8px;font-size:13px;color:var(--muted)}
.new-badge{display:inline-block;background:var(--badge-bg);color:var(--badge-ink);font-weight:700;font-size:12px;line-height:20px;padding:0 9px;border-radius:999px}
.index-page .post-body{font-size:15px;line-height:1.85;color:var(--muted);max-height:7.6em;overflow:hidden}
.index-page .post-body p{margin:0}
.card-more{display:inline-block;margin-top:14px;background:var(--chip);color:var(--chip-ink);font-weight:500;font-size:14px;letter-spacing:.06em;padding:6px 18px;border-radius:999px}
.card-more:hover{background:var(--accent);color:var(--on-accent)}
.index-page .jump-link{display:none}

/* 首篇放大 */
.index-page .blog-posts>.date-outer:first-child .date-posts>.post-outer:first-child{grid-column:1/-1;flex-direction:row}
.index-page .blog-posts>.date-outer:first-child .date-posts>.post-outer:first-child .card-thumb{flex:0 0 55%;aspect-ratio:auto;min-height:330px}
.index-page .blog-posts>.date-outer:first-child .date-posts>.post-outer:first-child .post{display:flex;flex-direction:column;justify-content:center;padding:28px 34px}
.index-page .blog-posts>.date-outer:first-child .date-posts>.post-outer:first-child h3.post-title{font-size:29px;line-height:1.45;-webkit-line-clamp:3}
.index-page .blog-posts>.date-outer:first-child .date-posts>.post-outer:first-child .post-body{font-size:16px;max-height:8.4em}

/* 滑入動畫（僅在 JS 載入成功後啟用） */
.js .index-page .post-outer,.js .sidebar .widget{opacity:0;translate:0 18px;transition:opacity .7s ease,translate .7s ease,transform .3s,box-shadow .3s,border-color .3s}
.js .index-page .post-outer.in,.js .sidebar .widget.in{opacity:1;translate:none}

/* ---------- 文章頁 ---------- */
.single .post-outer{padding:clamp(22px,4.5vw,52px);border-radius:24px}
.date-header{margin:0 0 12px}
.date-header span{display:inline-block;background:var(--accent-soft);color:var(--accent-ink);font-weight:700;font-size:13px;letter-spacing:.08em;padding:3px 14px;border-radius:999px}
.single h3.post-title{margin:4px 0 14px;font-weight:700;font-size:clamp(26px,4vw,36px);line-height:1.45;letter-spacing:.02em;color:var(--strong)}
.post-header{font-size:13px;color:var(--muted);margin-bottom:16px}
.post-footer{margin-top:28px;padding-top:16px;border-top:1px solid var(--line);font-size:13px;color:var(--muted);line-height:2}
.post-labels a{display:inline-block;background:var(--accent-soft);color:var(--accent-ink);font-size:12px;font-weight:700;letter-spacing:.06em;padding:1px 13px;margin:0 5px 4px 0;border-radius:999px}
.post-labels a:hover{background:var(--accent);color:var(--on-accent)}

.post-body{font-size:17px;line-height:2.05;color:var(--ink);word-wrap:break-word}
.single .post-body{max-width:780px}
.post-body img{border-radius:14px}
.post-body a{color:var(--accent-ink);font-weight:500;text-decoration:underline;text-decoration-color:var(--accent-line);text-decoration-thickness:2px;text-underline-offset:4px}
.post-body a:hover{text-decoration-color:var(--accent-ink)}
.post-body h2,.post-body h3,.post-body h4{font-weight:700;line-height:1.55;color:var(--strong);margin:2em 0 .7em}
.post-body h2{font-size:23px;padding:8px 18px;border-left:5px solid var(--accent);border-radius:4px 14px 14px 4px;background:var(--accent-soft)}
.post-body h3{font-size:20px;display:inline-block;border-bottom:3px solid var(--accent)}
.post-body blockquote{margin:1.6em 0;padding:14px 24px;background:var(--card-2);border-left:4px solid var(--accent);border-radius:4px 14px 14px 4px;color:var(--ink)}
.post-body table{width:100%;border-collapse:separate;border-spacing:0;margin:1.6em 0;font-size:15px;border:1px solid var(--line);border-radius:14px;overflow:hidden}
.post-body th{background:var(--accent-soft);color:var(--accent-ink);padding:11px 12px;font-weight:700;text-align:center;border-bottom:1px solid var(--line)}
.post-body td{padding:10px 12px;border-bottom:1px solid var(--line);text-align:center}
.post-body tr:last-child td{border-bottom:0}
.post-body tr:nth-child(even) td{background:var(--card-2)}
.post-body tr:hover td{background:var(--accent-soft)}

/* 投資文章專用小工具 */
.up{color:var(--up);font-weight:700}
.down{color:var(--down);font-weight:700}
.stock-tag{display:inline-block;background:var(--accent-soft);color:var(--accent-ink);font-weight:700;font-size:14px;padding:0 12px;margin:0 2px;border-radius:999px}
.key-point{background:var(--accent-soft);border:1px solid var(--accent-line);border-left:5px solid var(--accent);border-radius:4px 14px 14px 4px;padding:15px 20px;margin:1.6em 0}
.risk-note{background:var(--card-2);border:1px dashed var(--line);border-radius:12px;color:var(--muted);font-size:14px;padding:12px 18px;margin:1.6em 0}
.risk-note::before{content:'\26A0\A0\514D\8CAC\8072\660E\FF1A';font-weight:700;color:var(--strong)}
mark{background:linear-gradient(transparent 55%,var(--mark) 55%);color:inherit;padding:0 2px}

/* 自動目錄 */
.toc{background:var(--card-2);border:1px solid var(--line);border-radius:16px;padding:16px 22px;margin:0 0 30px;font-size:15px;line-height:1.95}
.toc b{display:block;font-weight:700;font-size:16px;letter-spacing:.08em;color:var(--strong)}
.toc ol{margin:6px 0 0;padding-left:1.4em}
.toc a{color:var(--ink);text-decoration:none;font-weight:400}
.toc a:hover{color:var(--accent-ink)}
.toc li.sub{margin-left:1.2em;list-style:circle}

/* 閱讀進度條 */
#progress{position:fixed;top:0;left:0;height:4px;width:0;background:var(--accent);border-radius:0 4px 4px 0;z-index:999;transition:width .1s linear}

/* 相關文章 */
.related{margin-top:30px}
.related h4,.cta h4{display:flex;align-items:center;gap:10px;margin:0 0 14px;font-weight:700;font-size:18px;letter-spacing:.06em;color:var(--strong)}
.related h4::before{content:'';width:10px;height:10px;border-radius:50%;background:var(--accent)}
.rel-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.rel-card{display:block;background:var(--card);border:1px solid var(--line);border-radius:16px;overflow:hidden;transition:transform .3s,border-color .3s}
.rel-card:hover{transform:translateY(-4px);border-color:var(--accent-line)}
.rel-card .card-thumb{aspect-ratio:16/9}
.rel-card div.t{padding:11px 16px 16px;font-weight:700;font-size:15px;line-height:1.6;color:var(--strong);display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}

/* 訂閱 CTA */
.cta{margin-top:28px;background:var(--accent-soft);border:1px solid var(--accent-line);border-radius:22px;padding:24px 30px;display:flex;gap:18px;align-items:center;justify-content:space-between;flex-wrap:wrap}
.cta h4{margin:0}
.cta p{margin:4px 0 0;font-size:14px;color:var(--ink)}
.cta a{background:var(--accent);color:var(--on-accent);font-weight:700;letter-spacing:.08em;padding:10px 24px;border-radius:999px;transition:transform .2s}
.cta a:hover{transform:translateY(-2px)}

/* 上下頁 */
.blog-pager{margin:28px 0 0;overflow:hidden;text-align:center}
.blog-pager a{display:inline-block;background:var(--card);color:var(--strong);border:1px solid var(--line);font-weight:500;letter-spacing:.06em;padding:9px 24px;border-radius:999px}
.blog-pager a:hover{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}
#blog-pager-newer-link{float:left}
#blog-pager-older-link{float:right}
.home-link{display:none}
.index-page .blog-pager{grid-column:1/-1}

/* 留言 */
.comments{margin-top:32px}
.comments h4{font-weight:700;color:var(--strong)}
.comments .comment-author{font-weight:700}
.comments .comment-block{border-left:3px solid var(--accent-line);padding-left:14px}
.post-share-buttons{margin-top:12px}

/* ---------- 側邊欄 ---------- */
.sidebar .widget{background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow-s);padding:20px 22px;margin:0 0 20px;transition:background .35s}
.widget>h2{display:flex;align-items:center;gap:10px;margin:0 0 14px;font-weight:700;font-size:17px;line-height:1.3;letter-spacing:.08em;color:var(--strong)}
.widget>h2::before{content:'';flex:0 0 auto;width:10px;height:10px;border-radius:50%;background:var(--accent)}
.widget ul{list-style:none;margin:0;padding:0;line-height:1.65}
.widget li{padding:10px 0;border-bottom:1px solid var(--line)}
.widget li:last-child{border-bottom:0}
.widget a:hover{color:var(--accent-ink)}

.cloud-label-widget-content{display:flex;flex-wrap:wrap;gap:8px}
.cloud-label-widget-content .label-size{font-size:13px}
.cloud-label-widget-content .label-size a{display:inline-block;padding:3px 14px;background:var(--chip);color:var(--chip-ink);border-radius:999px}
.cloud-label-widget-content .label-size a:hover{background:var(--accent);color:var(--on-accent)}
.label-size .label-count{margin-left:4px;color:var(--muted)}
.list-label-widget-content li a{font-weight:500;color:var(--strong)}
.label-count{float:right;color:var(--muted)}

.PopularPosts ul{counter-reset:rank}
.PopularPosts li{counter-increment:rank;overflow:hidden}
.PopularPosts .item-thumbnail{float:left;margin:0 14px 0 0}
.PopularPosts .item-thumbnail img{width:76px;height:76px;object-fit:cover;border-radius:14px}
.PopularPosts .item-title{font-weight:500;line-height:1.6;color:var(--strong)}
.PopularPosts .item-title::before{content:counter(rank);display:inline-block;width:22px;height:22px;line-height:22px;margin-right:8px;background:var(--accent-soft);color:var(--accent-ink);font-weight:700;font-size:12px;text-align:center;border-radius:50%}
.PopularPosts .item-snippet{display:none}

.BlogArchive ul.hierarchy{padding-left:14px}
.BlogArchive a.toggle{color:var(--muted)}
.BlogArchive .post-count{color:var(--muted)}

.BlogSearch table,.BlogSearch td{width:100%;border:0;padding:0}
.BlogSearch input[type=text],.BlogSearch input.gsc-input{width:100%;padding:10px 18px;border:1px solid var(--line);border-radius:999px;background:var(--card-2);color:var(--ink);font-family:var(--sans);outline:none;transition:border-color .2s,box-shadow .2s}
.BlogSearch input[type=text]:focus,.BlogSearch input.gsc-input:focus{border-color:var(--accent);box-shadow:0 0 0 4px var(--accent-soft)}
.BlogSearch input[type=submit],.BlogSearch input.gsc-search-button{margin-top:10px;background:var(--accent);color:var(--on-accent);border:0;border-radius:999px;font-weight:700;letter-spacing:.1em;padding:8px 24px;cursor:pointer}

.FollowByEmail table,.FollowByEmail td{width:100%;border:0;padding:0}
.follow-by-email-address{width:100%;padding:10px 18px;border:1px solid var(--line);border-radius:999px;background:var(--card-2);color:var(--ink);margin-bottom:10px;outline:none}
.follow-by-email-address:focus{border-color:var(--accent);box-shadow:0 0 0 4px var(--accent-soft)}
.follow-by-email-submit{background:var(--btn-bg);color:var(--btn-ink);border:1px solid var(--btn-line);border-radius:999px;font-weight:700;letter-spacing:.1em;padding:8px 26px;cursor:pointer}
.follow-by-email-submit:hover{background:var(--accent);color:var(--on-accent)}

/* ---------- 頁尾 ---------- */
.site-footer{background:var(--footer);color:#D5DDD8;border-radius:32px 32px 0 0;padding:38px 0 34px;font-size:14px}
.site-footer .brand{font-weight:900;font-size:21px;letter-spacing:.06em;color:#F4F7F5}
.site-footer .brand em{font-style:normal;color:var(--brand)}
.site-footer .tagline{letter-spacing:.3em;font-size:12px;color:#8F9A95;margin:2px 0 14px}
.site-footer .disclaimer{max-width:820px;line-height:1.95;color:#AAB5B0;background:rgba(255,255,255,.05);border-radius:14px;padding:14px 18px;margin:0}
.site-footer a{color:#7EE2B8}
.site-footer .Attribution{margin-top:18px;font-size:12px;color:#8F9A95}
.site-footer .widget{background:none;border:0;box-shadow:none;padding:0;margin:0}

/* 回到頂部 */
#toTop{position:fixed;right:20px;bottom:24px;width:46px;height:46px;border-radius:50%;background:var(--accent);color:var(--on-accent);border:0;box-shadow:0 8px 20px rgba(0,0,0,.25);font-size:19px;font-weight:700;cursor:pointer;opacity:0;pointer-events:none;transform:translateY(8px);transition:opacity .3s,transform .3s;z-index:70}
#toTop.show{opacity:1;pointer-events:auto;transform:none}

/* ---------- 響應式 ---------- */
@media (max-width:960px){
  .layout{grid-template-columns:1fr}
  .cat-tiles{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:720px){
  body{font-size:15px;padding-bottom:96px}
  .wrap{padding:0 14px}
  .masthead-inner{padding-top:16px}
  .Header h1.title::before{width:44px;height:44px;font-size:26px}
  .masthead .Header img,#Header1_headerimg{max-height:72px}
  .mast-tools #todayDate{display:none}

  /* 手機：頂部分段導覽收起，改用底部浮動膠囊 */
  .mainnav{display:none}
  .bottomnav{display:flex;position:fixed;left:12px;right:12px;bottom:calc(12px + env(safe-area-inset-bottom));max-width:520px;margin:0 auto;padding:6px;gap:2px;background:var(--card);border:1px solid var(--line);border-radius:30px;box-shadow:0 10px 30px rgba(0,0,0,.28);z-index:80}
  .bottomnav a{flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;padding:8px 2px 7px;border-radius:24px;font-size:11px;font-weight:500;letter-spacing:.02em;color:var(--muted);white-space:nowrap}
  .bottomnav svg{width:22px;height:22px}
  .bottomnav a.on{background:var(--pill-bg);color:var(--accent-ink);font-weight:700}
  #toTop{bottom:96px;right:14px}

  .index-page .blog-posts{grid-template-columns:1fr}
  .index-page .blog-posts>.date-outer:first-child .date-posts>.post-outer:first-child{flex-direction:column}
  .index-page .blog-posts>.date-outer:first-child .date-posts>.post-outer:first-child .card-thumb{flex:none;min-height:0;aspect-ratio:16/9}
  .index-page .blog-posts>.date-outer:first-child .date-posts>.post-outer:first-child .post{padding:18px 22px 24px}
  .index-page .blog-posts>.date-outer:first-child .date-posts>.post-outer:first-child h3.post-title{font-size:23px}
  .post-body{font-size:16px;line-height:2}
  .post-body h2{font-size:20px}
  .post-body table{display:block;overflow-x:auto;font-size:13px}
  .rel-grid{grid-template-columns:1fr}
  .cta{padding:20px 22px}
  .site-footer{border-radius:24px 24px 0 0}
}
@media (prefers-reduced-motion:reduce){
  *{animation:none!important;transition:none!important;scroll-behavior:auto!important}
  .js .index-page .post-outer,.js .sidebar .widget{opacity:1;translate:none}
}

/* =====================================================================
   全球新聞脈動 CSS（Blogger 版，無需 API Key）
   貼法：佈景主題 → 編輯 HTML → 搜尋 b:skin，整份貼在 b:skin 結尾標籤的正上方
   使用版型現有的顏色變數（--card、--line、--accent-soft 等），淺色／深色自動跟隨
   ===================================================================== */
/* ---------- 全球新聞脈動（新聞條列 + 摘要卡，無需 API Key） ---------- */
.news-pulse{margin-top:26px}
.np-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:12px}
.np-head h2{margin:0;display:flex;align-items:center;gap:10px;font-weight:900;font-size:22px;letter-spacing:.06em;color:var(--strong)}
.np-head h2::before{content:'';width:10px;height:10px;border-radius:50%;background:var(--up);animation:npPulse 1.8s infinite}
.np-updated{font-size:13px;color:var(--muted)}
.np-tabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px}
.np-tabs button{font:inherit;font-size:14px;font-weight:500;letter-spacing:.06em;padding:5px 16px;border-radius:999px;border:1px solid var(--line);background:var(--card);color:var(--muted);cursor:pointer}
.np-tabs button:hover{color:var(--strong)}
.np-tabs button.on{background:var(--accent-soft);border-color:var(--accent-line);color:var(--accent-ink);font-weight:700}
.np-list{background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow-s);overflow:hidden}
.np-row{display:block;width:100%;text-align:left;font:inherit;color:inherit;background:none;border:0;border-top:1px solid var(--line);padding:14px 20px;cursor:pointer}
.np-row:first-child{border-top:0}
.np-row:hover{background:var(--card-2)}
.np-meta{display:flex;align-items:center;flex-wrap:wrap;gap:4px 10px;font-size:12px;color:var(--muted)}
.np-tag{font-weight:700;letter-spacing:.06em;padding:1px 11px;border-radius:999px;background:var(--accent-soft);color:var(--accent-ink)}
.np-title{display:block;margin-top:4px;font-weight:700;font-size:16.5px;line-height:1.6;color:var(--strong)}
.np-row:hover .np-title{color:var(--accent-ink)}
.np-empty{padding:28px 20px;text-align:center;color:var(--muted)}
.np-note{margin:10px 2px 0;font-size:12px;color:var(--muted);line-height:1.7}

/* 摘要卡 */
#npCard{border:1px solid var(--line);border-radius:22px;background:var(--card);color:var(--ink);width:min(640px,calc(100vw - 28px));max-height:86vh;padding:22px 24px;box-shadow:var(--shadow)}
#npCard::backdrop{background:rgba(8,12,10,.6)}
.npc-bar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.npc-x{margin-left:auto;width:36px;height:36px;border-radius:50%;border:1px solid var(--btn-line);background:var(--btn-bg);color:var(--btn-ink);font-size:15px;cursor:pointer}
.npc-x:hover{background:var(--accent);color:var(--on-accent)}
#npCard h3{margin:12px 0 2px;font-weight:700;font-size:21px;line-height:1.5;color:var(--strong)}
.npc-orig{font-size:12.5px;color:var(--muted)}
#npCard h4{margin:16px 0 8px;font-size:13px;letter-spacing:.08em;color:var(--muted)}
.npc-pts{display:grid;gap:8px;margin:0;padding:14px 16px;list-style:none;background:var(--accent-soft);border-radius:14px;font-size:15.5px;line-height:1.8}
.npc-pts li{display:flex;gap:.6em;align-items:baseline}
.npc-pts li::before{content:'\2022';flex:none;width:.6em;text-align:center;color:var(--accent-ink)}
.npc-pts li span{min-width:0;overflow-wrap:anywhere}
.npc-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:18px}
.npc-foot small{font-size:12px;color:var(--muted)}
.npc-go{font:inherit;font-weight:700;letter-spacing:.08em;background:var(--accent);color:var(--on-accent);border:0;border-radius:999px;padding:9px 24px;cursor:pointer}
.npc-go:hover{transform:translateY(-1px)}
@keyframes npPulse{50%{opacity:.25}}
/* ---------- 首頁版面：沒有文章列表，側邊欄小工具改成橫向排列 ---------- */
.home-layout{grid-template-columns:1fr}
.home-layout .content{display:none}
.home-layout .sidebar .section{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;align-items:start}
.home-layout .sidebar .widget{margin:0}
@media (max-width:720px){.home-layout .sidebar .section{grid-template-columns:1fr}}

@media (max-width:720px){.np-head h2{font-size:19px}.np-row{padding:12px 16px}#npCard{padding:18px 18px}}
@media (prefers-reduced-motion:reduce){.np-head h2::before{animation:none!important}}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
(function () {
  var d = document, body = d.body;
  function $(s, r) { return (r || d).querySelector(s); }
  function $$(s, r) { return Array.prototype.slice.call((r || d).querySelectorAll(s)); }
  function safe(fn) { try { fn(); } catch (e) { } }

  /* ---- Blogger 圖片網址放大／縮成指定尺寸 ---- */
  function resize(src, size) {
    if (!src) { return src; }
    if (!/googleusercontent\.com|bp\.blogspot\.com/.test(src)) { return src; }
    return src
      .replace(/\/(?:s\d+|w\d+-h\d+)(?:-[a-z0-9-]+)?\/([^\/?#]+)$/i, '/' + size + '/$1')
      .replace(/=(?:s|w)\d+[^\/?#]*$/i, '=' + size);
  }

  /* ---- 單篇文章 / 靜態頁標記 ---- */
  if (body.classList.contains('item-page') || body.classList.contains('static_page-page')) {
    body.classList.add('single');
  }

  /* ---- 淺色／深色：預設跟隨系統，按鈕可手動覆寫 ---- */
  var root = d.documentElement;
  var mq = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;
  function isDark() {
    var t = root.getAttribute('data-theme');
    if (t) { return t === 'dark'; }
    return !!(mq && mq.matches);
  }
  function paintToggle() {
    var b = $('#themeToggle');
    if (!b) { return; }
    b.textContent = isDark() ? '☀' : '☾';
    b.setAttribute('aria-label', isDark() ? '切換為淺色模式' : '切換為深色模式');
  }
  safe(function () {
    var b = $('#themeToggle');
    if (!b) { return; }
    paintToggle();
    b.addEventListener('click', function () {
      var next = isDark() ? 'light' : 'dark';
      root.setAttribute('data-theme', next);
      safe(function () { localStorage.setItem('rv-theme', next); });
      paintToggle();
      safe(mountTicker);
    });
    if (mq && mq.addEventListener) {
      mq.addEventListener('change', function () {
        paintToggle();
        if (!root.getAttribute('data-theme')) { safe(mountTicker); }
      });
    }
  });

  /* ---- 今日日期 ---- */
  safe(function () {
    var el = $('#todayDate');
    if (!el) { return; }
    var n = new Date(), w = ['日', '一', '二', '三', '四', '五', '六'];
    el.textContent = n.getFullYear() + '年' + (n.getMonth() + 1) + '月' + n.getDate() + '日 週' + w[n.getDay()];
  });

  /* ---- 導覽列目前位置 ---- */
  safe(function () {
    var p = decodeURIComponent(location.pathname);
    $$('.mainnav a, .bottomnav a').forEach(function (a) {
      var k = a.getAttribute('data-key');
      if (k && p.indexOf('/search/label/' + k) === 0) { a.classList.add('on'); }
      if (a.getAttribute('data-home') && (p === '/' || p === '')) { a.classList.add('on'); }
    });
  });

  /* ---- 行情跑馬燈（TradingView 免費嵌入） ----
     一律使用「不透明」背景，由 TradingView 自己畫底色與文字色。
     原因：手機深色模式下，瀏覽器會把「透明的 iframe」強制塗成白底，
     而深色主題的文字是淺色，白底配淺色字就看不清楚。
     淺色主題底色為純白（與卡片同色）、深色主題為深色（與深色卡片近色），兩者都能融入頁面。 */
  function mountTicker() {
    var host = $('#ticker');
    if (!host) { return; }
    host.textContent = '';
    var box = d.createElement('div');
    box.className = 'tradingview-widget-container';
    var inner = d.createElement('div');
    inner.className = 'tradingview-widget-container__widget';
    box.appendChild(inner);
    var s = d.createElement('script');
    s.async = true;
    s.src = 'https://s3.tradingview.com/external-embedding/embed-widget-ticker-tape.js';
    s.innerHTML = JSON.stringify({
      symbols: [
        { proName: 'TWSE:TAIEX', title: '加權指數' },
        { proName: 'TWSE:2330', title: '台積電' },
        { proName: 'FOREXCOM:SPXUSD', title: '標普500' },
        { proName: 'FOREXCOM:NSXUSD', title: '那斯達克100' },
        { proName: 'FX_IDC:USDTWD', title: '美元/台幣' },
        { proName: 'BITSTAMP:BTCUSD', title: '比特幣' }
      ],
      showSymbolLogo: false,
      colorTheme: isDark() ? 'dark' : 'light',
      isTransparent: false,
      displayMode: 'adaptive',
      locale: 'zh_TW'
    });
    box.appendChild(s);
    host.appendChild(box);
  }
  safe(mountTicker);

  /* ---- 首頁 / 分類頁：把文章變成卡片 ---- */
  safe(function () {
    if (!body.classList.contains('index-page')) { return; }

    /* 首頁不顯示指定標籤的文章（分類頁、搜尋頁、封存頁不受影響）。要隱藏別的標籤，改這一行。 */
    var HIDE_ON_HOME = ['投資動態'];
    var pth = location.pathname;
    if ((pth === '/' || pth === '/search') && !/[?&]q=/.test(location.search)) {
      $$('.blog-posts .post-outer').forEach(function (po) {
        var hit = $$('.post-labels a', po).some(function (l) { return HIDE_ON_HOME.indexOf(l.textContent.trim()) > -1; });
        if (hit && po.parentNode) { po.parentNode.removeChild(po); }
      });
    }

    $$('.blog-posts .post-outer').forEach(function (po, idx) {
      var a = $('.post-title a', po), pb = $('.post-body', po);
      if (!pb) { return; }
      var href = a ? a.href : '#';
      var text = pb.textContent.replace(/\s+/g, ' ').trim();
      var im = $('img', pb);
      var label = $('.post-labels a', po);
      var pub = $('abbr.published', po) || $('.published', po);

      var thumb = d.createElement('a');
      thumb.className = 'card-thumb';
      thumb.href = href;
      if (im && im.getAttribute('src')) {
        var img = d.createElement('img');
        img.src = resize(im.getAttribute('src'), 'w800-h450-c');
        img.alt = '';
        img.loading = 'lazy';
        thumb.appendChild(img);
      } else {
        thumb.className += ' noimg';
        var r = d.createElement('span');
        r.textContent = 'R';
        thumb.appendChild(r);
      }
      if (label) {
        var tag = d.createElement('span');
        tag.className = 'card-tag';
        tag.textContent = label.textContent;
        thumb.appendChild(tag);
      }
      po.insertBefore(thumb, po.firstChild);

      var meta = d.createElement('div');
      meta.className = 'card-meta';
      if (pub) {
        var iso = pub.getAttribute('title') || '';
        var dt = iso ? iso.slice(0, 10).replace(/-/g, '.') : pub.textContent;
        var ts = Date.parse(iso);
        if (ts && (Date.now() - ts) < 72 * 3600 * 1000) {
          var nb = d.createElement('span');
          nb.className = 'new-badge';
          nb.textContent = '新';
          meta.appendChild(nb);
        }
        var s1 = d.createElement('span');
        s1.textContent = dt;
        meta.appendChild(s1);
      }
      var mins = Math.max(1, Math.round(text.length / 450));
      var s2 = d.createElement('span');
      s2.textContent = '約 ' + mins + ' 分鐘閱讀';
      meta.appendChild(s2);
      var t = $('.post-title', po);
      if (t && t.parentNode) { t.parentNode.insertBefore(meta, t.nextSibling); }

      var limit = idx === 0 ? 170 : 90;
      var snippet = text.length > limit ? text.slice(0, limit) + '…' : text;
      pb.textContent = '';
      var p = d.createElement('p');
      p.textContent = snippet;
      pb.appendChild(p);

      var more = d.createElement('a');
      more.className = 'card-more';
      more.href = href;
      more.textContent = '閱讀全文 ›';
      pb.parentNode.insertBefore(more, pb.nextSibling);
    });
  });

  /* ---- 文章頁：進度條 / 目錄 / 相關文章 / 訂閱區 ---- */
  safe(function () {
    if (!body.classList.contains('item-page')) { return; }
    var pb = $('.post-body');
    if (!pb) { return; }

    var bar = $('#progress');
    window.addEventListener('scroll', function () {
      var h = d.documentElement, m = h.scrollHeight - h.clientHeight;
      if (bar) { bar.style.width = (m > 0 ? (h.scrollTop / m) * 100 : 0) + '%'; }
    }, { passive: true });

    var hs = $$('h2, h3', pb);
    if (hs.length >= 3) {
      var toc = d.createElement('nav');
      toc.className = 'toc';
      var tt = d.createElement('b');
      tt.textContent = '本文重點導覽';
      toc.appendChild(tt);
      var ol = d.createElement('ol');
      hs.forEach(function (h, i) {
        h.id = h.id || 'sec-' + (i + 1);
        var li = d.createElement('li');
        if (h.tagName === 'H3') { li.className = 'sub'; }
        var a = d.createElement('a');
        a.href = '#' + h.id;
        a.textContent = h.textContent;
        li.appendChild(a);
        ol.appendChild(li);
      });
      toc.appendChild(ol);
      pb.insertBefore(toc, pb.firstChild);
    }

    var host = $('.blog-posts');
    if (!host) { return; }

    var cta = d.createElement('div');
    cta.className = 'cta';
    var left = d.createElement('div');
    var h4 = d.createElement('h4');
    h4.textContent = '不錯過每一篇觀點';
    var cp = d.createElement('p');
    cp.textContent = '訂閱 RSS，投資動態、產業文章、個股分享與產經新聞第一時間掌握。';
    left.appendChild(h4);
    left.appendChild(cp);
    var ca = d.createElement('a');
    ca.href = '/feeds/posts/default?alt=rss';
    ca.target = '_blank';
    ca.textContent = 'RSS 訂閱';
    cta.appendChild(left);
    cta.appendChild(ca);
    host.appendChild(cta);

    var lab = $('.post-labels a[rel="tag"]') || $('.post-labels a');
    if (!lab || !window.fetch) { return; }
    var url = '/feeds/posts/default/-/' + encodeURIComponent(lab.textContent.trim()) + '?alt=json&max-results=6';
    fetch(url).then(function (r) { return r.json(); }).then(function (j) {
      var es = (j.feed && j.feed.entry) || [];
      var cards = [];
      es.forEach(function (e) {
        var lk = (e.link || []).filter(function (l) { return l.rel === 'alternate'; })[0];
        if (!lk) { return; }
        var tmp = d.createElement('a');
        tmp.href = lk.href;
        if (tmp.pathname === location.pathname) { return; }
        if (cards.length >= 3) { return; }
        cards.push({ href: lk.href, title: e.title.$t, img: e['media$thumbnail'] ? e['media$thumbnail'].url : '' });
      });
      if (!cards.length) { return; }
      var sec = d.createElement('section');
      sec.className = 'related';
      var rh = d.createElement('h4');
      rh.textContent = '延伸閱讀';
      sec.appendChild(rh);
      var grid = d.createElement('div');
      grid.className = 'rel-grid';
      cards.forEach(function (c) {
        var a = d.createElement('a');
        a.className = 'rel-card';
        a.href = c.href;
        var th = d.createElement('span');
        th.className = 'card-thumb' + (c.img ? '' : ' noimg');
        if (c.img) {
          var im = d.createElement('img');
          im.src = resize(c.img, 'w480-h270-c');
          im.alt = '';
          im.loading = 'lazy';
          th.appendChild(im);
        } else {
          var rr = d.createElement('span');
          rr.textContent = 'R';
          th.appendChild(rr);
        }
        var tx = d.createElement('div');
        tx.className = 't';
        tx.textContent = c.title;
        a.appendChild(th);
        a.appendChild(tx);
        grid.appendChild(a);
      });
      sec.appendChild(grid);
      host.appendChild(sec);
    }).catch(function () { });
  });

  /* ---- 回到頂部 ---- */
  safe(function () {
    var b = $('#toTop');
    if (!b) { return; }
    window.addEventListener('scroll', function () {
      b.classList.toggle('show', (d.documentElement.scrollTop || body.scrollTop) > 600);
    }, { passive: true });
    b.addEventListener('click', function () { window.scrollTo({ top: 0, behavior: 'smooth' }); });
  });

  /* ---- 滑入動畫（放最後，等卡片建好） ---- */
  safe(function () {
    if (!('IntersectionObserver' in window)) { return; }
    var io = new IntersectionObserver(function (es) {
      es.forEach(function (e) {
        if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); }
      });
    }, { threshold: 0.06 });
    var els = $$('.index-page .post-outer, .sidebar .widget');
    d.documentElement.classList.add('js');
    els.forEach(function (el) { io.observe(el); });
  });
})();
